PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS games(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL,name TEXT NOT NULL,correct_count INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'playing',active_question TEXT,selected_ids TEXT NOT NULL DEFAULT '[]',lifelines TEXT NOT NULL DEFAULT '[]',fifty_removed TEXT NOT NULL DEFAULT '[]',fifty_level INTEGER,payout INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS games_expiry ON games(expires_at);
CREATE TABLE IF NOT EXISTS answers(game_id TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,level INTEGER NOT NULL,question_id TEXT NOT NULL,choice INTEGER NOT NULL,correct INTEGER NOT NULL,PRIMARY KEY(game_id,level));
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS email_challenges(game_id TEXT PRIMARY KEY REFERENCES games(id) ON DELETE CASCADE,email TEXT NOT NULL,salt TEXT NOT NULL,challenge_hash TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,expires_at INTEGER NOT NULL);
